export function updateExteriorDetail(w,s){const event=s.alleyEvent;for(let i=0;i<w.rattleBins.length;i++){const b=w.rattleBins[i],age=event?s.time-event.time:99,active=event?.bin===i&&age<3;const decay=active?Math.max(0,1-age/3):0;b.root.rotation.z=Math.sin(age*37)*.025*decay;b.root.position.x=b.x+Math.sin(age*29)*.025*decay;b.lid.rotation.x=-Math.max(0,Math.sin(age*19))*.23*decay;}}
